<script setup lang="ts">
definePageMeta({middleware:['auth']})
const {canEdit}=useWorkspace(),cursor=ref<string|undefined>(),stack=ref<(string|undefined)[]>([]),failure=ref('')
const {data,pending,error,refresh}=await useFetch<any>('/api/v1/maintenances',{query:computed(()=>({limit:100,cursor:cursor.value})),headers:useRequestHeaders(['cookie'])})
async function action(id:number,operation:string){failure.value='';try{if(operation==='delete')await $fetch('/api/v1/maintenances/'+id,{method:'DELETE'});else await $fetch('/api/v1/maintenances/'+id+'/'+operation,{method:'POST'});await refresh()}catch{failure.value='Unable to update maintenance'}}
function next(){if(!data.value?.page.nextCursor)return;stack.value.push(cursor.value);cursor.value=data.value.page.nextCursor}
function back(){cursor.value=stack.value.pop()}
</script>
<template>
 <div><div class="flex flex-wrap gap-4 items-start justify-between mb-6"><div><h1 class="text-2xl font-semibold">Maintenance windows</h1><p class="text-gray-400 mt-1">Manage planned downtime across this workspace.</p></div><NuxtLink v-if="canEdit" to="/maintenance/add" class="btn btn-primary">Schedule maintenance</NuxtLink></div>
 <p v-if="failure||error" role="alert" class="text-red-400 mb-3">{{failure||'Unable to load maintenance'}}</p><p v-if="pending">Loading…</p>
 <div v-else class="space-y-3"><p v-if="!data?.data?.length" class="card p-8 text-gray-400">No maintenance windows scheduled.</p><article v-for="item in data?.data||[]" :key="item.id" class="card p-4 sm:p-5 flex flex-col sm:flex-row gap-4 justify-between"><div class="min-w-0"><NuxtLink :to="`/maintenance/${item.id}`" class="font-medium text-lg break-words">{{item.title}}</NuxtLink><p class="text-sm text-gray-400 mt-1">{{item.strategy}} · {{item.timezone}} · <span :class="item.status==='under-maintenance'?'text-blue-400':''">{{item.status}}</span></p><p v-if="item.description" class="text-sm mt-2 break-words">{{item.description}}</p><p v-if="item.startDate" class="text-sm text-gray-400 mt-2"><ClientOnly>{{new Date(item.startDate).toLocaleString()}} → {{item.endDate?new Date(item.endDate).toLocaleString():'No end date'}}<template #fallback>—</template></ClientOnly></p></div><div v-if="canEdit" class="flex flex-wrap gap-2 sm:items-start shrink-0"><button class="btn btn-secondary" @click="action(item.id,item.active?'pause':'resume')">{{item.active?'Pause':'Resume'}}</button><NuxtLink :to="`/maintenance/${item.id}/edit`" class="btn btn-secondary">Edit</NuxtLink><button class="btn btn-secondary text-red-400" @click="action(item.id,'delete')">Delete</button></div></article></div>
 <div class="flex justify-between mt-5"><button class="btn btn-secondary" :disabled="!stack.length||pending" @click="back">Previous page</button><button class="btn btn-secondary" :disabled="!data?.page.hasMore||pending" @click="next">Next page</button></div></div>
</template>
